// Creates exactly 100 fictional patients, registered between 7:00:00 AM and 5:00:00 PM Manila time
// on one business date. Each one gets what Front Desk registration creates: a permanent
// patient_records row (PAT-xxxx, generated by the database) and a waiting queue visit in patients.
//
//   node seed/seed-dummy-patients.js [--date=YYYY-MM-DD]        Dry run. Reads only, writes nothing.
//   node seed/seed-dummy-patients.js --apply --confirm-project=<ref> [--date=...] [--allow-future]
//   node seed/seed-dummy-patients.js --verify
//   node seed/seed-dummy-patients.js --remove --confirm-project=<ref>
//
// <ref> is the subdomain of SUPABASE_URL. Typing it is the deliberate step that names the target.
//
// Dummy data is found only through patient_records.created_by = SEED_MARKER; a dummy visit is one
// whose patient_record_id points at such a record. Visits keep source "website", the value Front
// Desk registration stores, so dashboards treat them the same way. No schema change is needed.
// Mobile numbers are left empty (the field is optional) because a made-up number could belong to a
// real person, and calling a visit sends that number an SMS.
const crypto = require("node:crypto");
const { getBusinessDate, getBusinessDayRange } = require("../src/lib/businessDay");

const SEED_MARKER = "seed:dummy-patients-v1";
const PATIENT_COUNT = 100;
const RANDOM_SEED = 20261106;
const WINDOW_START_SECONDS = 7 * 3600;
const WINDOW_END_SECONDS = 17 * 3600;
const MANILA_OFFSET_MS = 8 * 3600 * 1000;
const PAGE_SIZE = 1000;

// Mirror of backend/src/services/queueService.js, which does not export these.
const SERVICE_CODE_MAP = { consultation: "GP", checkup: "GP", prenatal: "OB", maternity: "OB", family_planning: "FP" };
const VULNERABILITY_WEIGHTS = { senior: 4, pwd: 3, pregnant: 3, indigenous: 2, solo_parent: 1 };
const SENIOR_AGE = 60;

const FEMALE_NAMES = ["Maria Lourdes", "Rosario", "Liza", "Carmela", "Jocelyn", "Marites", "Analyn", "Rowena", "Teresita",
  "Divina", "Cristina", "Maricel", "Lorna", "Aileen", "Gemma", "Imelda", "Corazon", "Josefina", "Editha", "Nenita",
  "Rhea", "Angelica", "Kristine", "Princess", "Jasmine", "Hazel", "Camille", "Bea", "Trisha", "Mylene"];
const MALE_NAMES = ["Rodrigo", "Ernesto", "Romeo", "Danilo", "Reynaldo", "Rolando", "Eduardo", "Renato", "Virgilio",
  "Rogelio", "Benjamin", "Arnel", "Noel", "Jomar", "Ronnie", "Jerome", "Mark Anthony", "John Paul", "Christian", "Paolo",
  "Carlo", "Miguel", "Rafael", "Gabriel", "Joshua", "Nathaniel", "Emmanuel", "Dennis", "Alvin", "Marlon"];
const LAST_NAMES = ["Dela Cruz", "Santos", "Reyes", "Bautista", "Ocampo", "Garcia", "Mendoza", "Torres", "Tomas",
  "Andrada", "Castillo", "Flores", "Villanueva", "Ramos", "Castro", "Rivera", "Aquino", "Navarro", "Salazar", "Mercado",
  "Del Rosario", "Gonzales", "Lopez", "Hernandez", "Perez", "De Guzman", "Pascual", "Dimaculangan", "Magbanua", "Panganiban",
  "Macaraeg", "Dimaano", "Sumulong", "Batungbakal", "Lacsamana", "Manalo", "Pangilinan", "Evangelista", "Soriano", "Aguilar"];
const STREETS = ["Sampaguita", "Ilang-Ilang", "Narra", "Molave", "Kamagong", "Rosal", "Mabini", "Rizal"];

function fail(message) {
  const error = new Error(message);
  error.expected = true;
  return error;
}

function createRandom(seed) {
  let state = seed >>> 0;
  const next = () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let t = state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
  return { next, int: (min, max) => min + Math.floor(next() * (max - min + 1)), pick: (list) => list[Math.floor(next() * list.length)] };
}

function nameSearchWords(value) {
  return String(value ?? "").normalize("NFC").toLowerCase()
    .replace(/[^\p{L}\p{N}'\s-]/gu, " ").split(/\s+/).filter(Boolean);
}

const nameKey = (value) => nameSearchWords(value).join(" ");

function ageOn(date, birthdate) {
  const [year, month, day] = date.split("-").map(Number);
  const [birthYear, birthMonth, birthDay] = birthdate.split("-").map(Number);
  return year - birthYear - ((month * 100 + day) < (birthMonth * 100 + birthDay) ? 1 : 0);
}

function randomBirthdate(random, date, age) {
  const birthYear = Number(date.slice(0, 4)) - age;
  const month = random.int(1, 12);
  // Day 28 exists in every month and every year.
  const birthdate = `${birthYear}-${String(month).padStart(2, "0")}-${String(random.int(1, 28)).padStart(2, "0")}`;
  return birthdate > date ? `${birthYear - 1}${birthdate.slice(4)}` : birthdate;
}

function randomProfile(random, date) {
  const roll = random.next();
  const serviceType = roll < 0.35 ? "consultation" : roll < 0.6 ? "checkup" : roll < 0.75 ? "prenatal" : roll < 0.85 ? "maternity" : "family_planning";
  const motherCare = serviceType === "prenatal" || serviceType === "maternity";
  const sex = motherCare || random.next() < 0.55 ? "Female" : "Male";
  const age = motherCare ? random.int(18, 42) : serviceType === "family_planning" ? random.int(18, 45)
    : random.next() < 0.3 ? random.int(60, 88) : random.int(1, 59);
  const birthdate = randomBirthdate(random, date, age);
  const flags = [];
  // The registration form ticks Senior Citizen itself from the birthdate.
  if (ageOn(date, birthdate) >= SENIOR_AGE) flags.push("senior");
  if (serviceType === "prenatal" || (serviceType === "maternity" && random.next() < 0.5)) flags.push("pregnant");
  if (random.next() < 0.06) flags.push("pwd");
  if (random.next() < 0.03) flags.push("indigenous");
  if (age >= 18 && random.next() < 0.06) flags.push("solo_parent");
  return { serviceType, sex, birthdate, flags };
}

function randomTimestamps(random, date, count) {
  const midnight = Date.parse(getBusinessDayRange(date).start);
  const seconds = Array.from({ length: count }, () => random.int(WINDOW_START_SECONDS, WINDOW_END_SECONDS));
  return seconds.sort((a, b) => a - b).map((value) => new Date(midnight + value * 1000).toISOString());
}

// Same data for the same date and database contents, so a dry run shows what --apply will write.
function buildDataset({ date, usedNames = new Set(), maxSequence = {} }) {
  const random = createRandom(RANDOM_SEED + Number(date.replaceAll("-", "")));
  const taken = new Set(usedNames);
  const sequence = { GP: 0, OB: 0, FP: 0, ...maxSequence };
  return randomTimestamps(random, date, PATIENT_COUNT).map((createdAt) => {
    const { serviceType, sex, birthdate, flags } = randomProfile(random, date);
    let firstName, lastName, middleInitial, fullName;
    do {
      firstName = random.pick(sex === "Female" ? FEMALE_NAMES : MALE_NAMES);
      lastName = random.pick(LAST_NAMES);
      middleInitial = random.next() < 0.8 ? String.fromCharCode(random.int(65, 90)) : "";
      fullName = [firstName, middleInitial ? `${middleInitial}.` : "", lastName].filter(Boolean).join(" ");
    } while (taken.has(nameKey(`${firstName} ${lastName}`)));
    taken.add(nameKey(`${firstName} ${lastName}`));

    const code = SERVICE_CODE_MAP[serviceType];
    sequence[code] += 1;
    const score = flags.reduce((total, flag) => total + VULNERABILITY_WEIGHTS[flag], 0);
    const residency = `Blk ${random.int(1, 40)} Lot ${random.int(1, 30)}, ${random.pick(STREETS)} St., Brgy. Sample ${random.int(1, 12)}, Test City (TEST DATA)`;
    return {
      record: {
        first_name: firstName,
        middle_initial: middleInitial || null,
        last_name: lastName,
        full_name: fullName,
        search_name: nameSearchWords(fullName).join(" "),
        birthdate,
        sex,
        mobile_number: null,
        residency,
        philhealth_id: null,
        created_by: SEED_MARKER,
        created_at: createdAt
      },
      visit: {
        queue_number: `${code}-${String(sequence[code]).padStart(3, "0")}`,
        id_num: fullName,
        service_type: serviceType,
        mobile_number: null,
        residency,
        philhealth_id: null,
        birthdate,
        sex,
        priority_score: score === 0 ? 1 : score,
        vulnerability_flags: flags,
        source: "website",
        status: "waiting",
        created_at: createdAt
      }
    };
  });
}

function must({ data, error }, action) {
  if (error) throw fail(`${action} failed: ${error.code || ""} ${error.message}`.trim());
  return data;
}

async function readAll(client, table, columns) {
  const rows = [];
  for (let page = 0; ; page += 1) {
    const data = must(await client.from(table).select(columns).order("id").range(page * PAGE_SIZE, (page + 1) * PAGE_SIZE - 1), `Reading ${table}`);
    rows.push(...data);
    if (data.length < PAGE_SIZE) return rows;
  }
}

async function readDummyRecords(client) {
  return must(await client.from("patient_records").select("id, patient_code, full_name, search_name, sex, birthdate, residency, created_at")
    .eq("created_by", SEED_MARKER).order("id"), "Reading dummy records");
}

async function readDummyVisits(client, records) {
  const ids = records.map((record) => record.id);
  if (!ids.length) return [];
  return must(await client.from("patients").select("id, patient_record_id, id_num, queue_number, service_type, status, source, priority_score, created_at")
    .in("patient_record_id", ids).order("id"), "Reading dummy visits");
}

// What createQueueEntry computes: the highest standard number ever issued for each service code.
async function loadExisting(client) {
  const [visits, records] = await Promise.all([
    readAll(client, "patients", "id, id_num, queue_number"),
    readAll(client, "patient_records", "id, first_name, last_name")
  ]);
  const maxSequence = {};
  for (const { queue_number: queueNumber } of visits) {
    const match = /^(GP|OB|FP)-(\d+)$/.exec(String(queueNumber || ""));
    if (match) maxSequence[match[1]] = Math.max(maxSequence[match[1]] || 0, Number(match[2]));
  }
  const usedNames = new Set([
    ...records.map((record) => nameKey(`${record.first_name} ${record.last_name}`)),
    ...visits.map((visit) => nameKey(visit.id_num))
  ]);
  return { usedNames, maxSequence };
}

// Fingerprint of the rows the seed must leave alone. Live registrations during a run change it.
async function fingerprintOtherRows(client, skip = { records: [], visits: [] }) {
  const skipRecords = new Set(skip.records), skipVisits = new Set(skip.visits);
  const [visits, records] = await Promise.all([readAll(client, "patients", "*"), readAll(client, "patient_records", "*")]);
  const rows = [...visits.filter((row) => !skipVisits.has(row.id)), ...records.filter((row) => !skipRecords.has(row.id))];
  return { rows: rows.length, hash: crypto.createHash("sha256").update(JSON.stringify(rows)).digest("hex") };
}

function assertTargetAllowed({ projectRef, confirmProject, nodeEnv }) {
  if (nodeEnv === "production") throw fail("Refused: NODE_ENV is production.");
  if (!confirmProject) throw fail("Refused: add --confirm-project=<ref> to name the target project.");
  if (confirmProject !== projectRef) throw fail("Refused: --confirm-project does not match the project in SUPABASE_URL.");
}

function checkDataset(records, visits, date) {
  const { start } = getBusinessDayRange(date);
  const earliest = Date.parse(start) + WINDOW_START_SECONDS * 1000;
  const latest = Date.parse(start) + WINDOW_END_SECONDS * 1000;
  const inWindow = (row) => Date.parse(row.created_at) >= earliest && Date.parse(row.created_at) <= latest;
  const recordIds = new Set(records.map((record) => record.id));
  return {
    "exactly 100 dummy records": records.length === PATIENT_COUNT,
    "exactly 100 dummy visits": visits.length === PATIENT_COUNT,
    "one visit per record": new Set(visits.map((visit) => visit.patient_record_id)).size === PATIENT_COUNT && visits.every((visit) => recordIds.has(visit.patient_record_id)),
    "Patient IDs present and unique": records.every((record) => record.patient_code) && new Set(records.map((record) => record.patient_code)).size === records.length,
    "queue numbers unique": new Set(visits.map((visit) => visit.queue_number)).size === visits.length,
    "all timestamps inside the window": records.every(inWindow) && visits.every(inWindow),
    "all on one business date": [...records, ...visits].every((row) => getBusinessDate(row.created_at) === date)
  };
}

function printChecks(checks) {
  for (const [name, passed] of Object.entries(checks)) console.log(`  [${passed ? "x" : " "}] ${name}`);
  return Object.values(checks).every(Boolean);
}

const manilaTime = (iso) => new Date(Date.parse(iso) + MANILA_OFFSET_MS).toISOString().slice(11, 19);

function summarize(dataset) {
  const count = (values) => values.reduce((totals, value) => ({ ...totals, [value]: (totals[value] || 0) + 1 }), {});
  const times = dataset.map((row) => row.visit.created_at);
  console.log(`  Patients: ${dataset.length}`);
  console.log(`  First and last registration (Manila): ${manilaTime(times[0])} to ${manilaTime(times.at(-1))}`);
  console.log(`  Services: ${JSON.stringify(count(dataset.map((row) => row.visit.service_type)))}`);
  console.log(`  Regular / Vulnerable: ${dataset.filter((row) => !row.visit.vulnerability_flags.length).length} / ${dataset.filter((row) => row.visit.vulnerability_flags.length).length}`);
  for (const code of ["GP", "OB", "FP"]) {
    const numbers = dataset.map((row) => row.visit.queue_number).filter((number) => number.startsWith(code));
    if (numbers.length) console.log(`  ${code} queue numbers: ${numbers[0]} to ${numbers.at(-1)} (${numbers.length})`);
  }
}

async function dryRun(client, { date, now }) {
  const existing = await readDummyRecords(client);
  if (existing.length) console.log(`Already seeded: ${existing.length} dummy records exist. --apply would stop.`);
  const dataset = buildDataset({ date, ...(await loadExisting(client)) });
  console.log(`DRY RUN. Nothing was written. Date: ${date} (Asia/Manila)`);
  summarize(dataset);
  console.table(dataset.slice(0, 5).map(({ record, visit }) => ({
    time: manilaTime(visit.created_at), name: record.full_name, sex: record.sex, birthdate: record.birthdate,
    queue: visit.queue_number, service: visit.service_type, score: visit.priority_score
  })));
  if (Date.parse(dataset.at(-1).visit.created_at) > now.getTime()) {
    console.log("Some of these times are still in the future; --apply stops unless --allow-future is added.");
  }
  return dataset;
}

async function apply(client, { date, now, allowFuture }) {
  if ((await readDummyRecords(client)).length) throw fail("Stopped: dummy patients already exist. Nothing was added. Use --remove first to reseed.");
  const dataset = buildDataset({ date, ...(await loadExisting(client)) });
  if (!allowFuture && Date.parse(dataset.at(-1).visit.created_at) > now.getTime()) {
    throw fail(`Stopped: the last registration time is still in the future. Run after ${manilaTime(dataset.at(-1).visit.created_at)} Manila time, use an earlier --date, or add --allow-future.`);
  }

  const before = await fingerprintOtherRows(client);
  // Each array insert is one all-or-nothing statement.
  const records = must(await client.from("patient_records").insert(dataset.map((row) => row.record)).select("id, full_name"), "Inserting dummy records");
  const idByName = new Map(records.map((record) => [record.full_name, record.id]));
  const visitInsert = await client.from("patients")
    .insert(dataset.map((row) => ({ ...row.visit, patient_record_id: idByName.get(row.record.full_name) }))).select("id");
  if (visitInsert.error) {
    must(await client.from("patient_records").delete().eq("created_by", SEED_MARKER), "Undoing dummy records");
    throw fail(`Inserting dummy visits failed, and the dummy records were removed: ${visitInsert.error.code || ""} ${visitInsert.error.message}`);
  }

  const dummyRecords = await readDummyRecords(client);
  const dummyVisits = await readDummyVisits(client, dummyRecords);
  const after = await fingerprintOtherRows(client, { records: dummyRecords.map((row) => row.id), visits: dummyVisits.map((row) => row.id) });
  console.log(`Inserted ${dummyRecords.length} patient_records and ${dummyVisits.length} patients rows for ${date}.`);
  summarize(dataset);
  const passed = printChecks({
    ...checkDataset(dummyRecords, dummyVisits, date),
    "existing rows unchanged": before.rows === after.rows && before.hash === after.hash
  });
  if (!passed) throw fail("Inserted, but a check failed. See the list above.");
}

async function verify(client) {
  const records = await readDummyRecords(client);
  if (!records.length) throw fail("No dummy patients found.");
  const visits = await readDummyVisits(client, records);
  const date = getBusinessDate(records[0].created_at);
  const times = records.map((record) => record.created_at).sort();
  console.log(`Date: ${date}. Registrations (Manila): ${manilaTime(times[0])} to ${manilaTime(times.at(-1))}.`);
  if (!printChecks(checkDataset(records, visits, date))) throw fail("A check failed. See the list above.");
}

async function remove(client) {
  const records = await readDummyRecords(client);
  if (!records.length) {
    console.log("No dummy patients found. Nothing to remove.");
    return;
  }
  const visits = await readDummyVisits(client, records);
  const visitIds = new Set(visits.map((visit) => visit.id));
  const counters = must(await client.from("counters").select("id, current_patient_id"), "Reading counters");
  if (visits.some((visit) => visit.status === "serving") || counters.some((counter) => visitIds.has(counter.current_patient_id))) {
    throw fail("Stopped: a dummy patient is being served. Finish or cancel that visit, then remove again. Nothing was deleted.");
  }
  const before = await fingerprintOtherRows(client, { records: records.map((row) => row.id), visits: [...visitIds] });
  if (visits.length) {
    must(await client.from("patients").delete().in("id", [...visitIds]), "Deleting dummy visits");
  }
  must(await client.from("patient_records").delete().eq("created_by", SEED_MARKER), "Deleting dummy records");
  const after = await fingerprintOtherRows(client);
  console.log(`Removed ${visits.length} visits and ${records.length} records.`);
  if (before.rows !== after.rows || before.hash !== after.hash) console.log("Other rows changed during the removal; check for live activity.");
}

function parseArgs(argv) {
  const options = { mode: "dry-run", allowFuture: false };
  for (const arg of argv) {
    if (arg === "--apply" || arg === "--verify" || arg === "--remove") options.mode = arg.slice(2);
    else if (arg === "--allow-future") options.allowFuture = true;
    else if (arg.startsWith("--date=")) options.date = arg.slice(7);
    else if (arg.startsWith("--confirm-project=")) options.confirmProject = arg.slice(18);
    else throw fail(`Unknown option ${arg}.`);
  }
  return options;
}

async function main(argv = process.argv.slice(2)) {
  const options = parseArgs(argv);
  const now = new Date();
  const date = options.date || getBusinessDate(now);
  getBusinessDayRange(date); // rejects an invalid date
  const env = require("../src/config/env");
  if (!env.supabaseUrl || !env.supabaseServiceRoleKey) throw fail("SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY are required.");
  const projectRef = new URL(env.supabaseUrl).hostname.split(".")[0];
  if (options.mode === "apply" || options.mode === "remove") {
    assertTargetAllowed({ projectRef, confirmProject: options.confirmProject, nodeEnv: process.env.NODE_ENV });
  }
  const client = require("../src/lib/supabase");
  if (options.mode === "apply") await apply(client, { date, now, allowFuture: options.allowFuture });
  else if (options.mode === "verify") await verify(client);
  else if (options.mode === "remove") await remove(client);
  else await dryRun(client, { date, now });
}

if (require.main === module) {
  main().catch((error) => {
    console.error(error.expected ? error.message : error);
    process.exitCode = 1;
  });
}

module.exports = { SEED_MARKER, PATIENT_COUNT, assertTargetAllowed, buildDataset, checkDataset, dryRun, apply, verify, remove, parseArgs };
